package com.mediahub.tv;
import android.app.*;import android.os.*;import android.graphics.Color;import android.content.*;import android.view.*;import android.widget.*;import androidx.media3.common.*;import androidx.media3.exoplayer.ExoPlayer;import androidx.media3.ui.PlayerView;import org.json.*;import java.net.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,bar,rows; ExoPlayer player; JSONArray sources=new JSONArray(); Set<String> favorites=new HashSet<>(); ArrayList<Channel> channels=new ArrayList<>(); String tab="All"; EditText search; int generation=0;
 static class Channel { final String n,u,g; Channel(String n,String u,String g){this.n=n;this.u=u;this.g=g;} String name(){return n;} String url(){return u;} String group(){return g;} }
 public void onCreate(Bundle b){super.onCreate(b);try{sources=new JSONArray(getPreferences(0).getString("sources","[]"));}catch(Exception e){} favorites=new HashSet<>(getPreferences(0).getStringSet("favorites",new HashSet<>()));home();}
 void save(){getPreferences(0).edit().putString("sources",sources.toString()).putStringSet("favorites",new HashSet<>(favorites)).apply();}
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(dp(12),dp(8),dp(12),dp(8));return t;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setFocusable(true);b.setOnClickListener(v->r.run());return b;}
 void base(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(16),dp(24),dp(16));root.setBackgroundColor(0xff101923);setContentView(root);}
 void home(){release();base();root.addView(text("MEDIAHUB TV  •  Live TV / ภาพยนตร์",25));bar=new LinearLayout(this);root.addView(bar);for(String s:new String[]{"All","Favorites","Sources"})bar.addView(button(s,()->{tab=s;home();}));bar.addView(button("+ Add source",()->add()));bar.addView(button("Refresh",()->load()));search=new EditText(this);search.setSingleLine(true);search.setHint("Search / ค้นหา");root.addView(search);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(android.text.Editable e){}});ScrollView sc=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(1);sc.addView(rows);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));render();if(channels.isEmpty()&&sources.length()>0&&!tab.equals("Sources"))load();}
 void render(){if(rows==null)return;rows.removeAllViews();if(tab.equals("Sources")){for(int i=0;i<sources.length();i++){final int n=i;JSONObject o=sources.optJSONObject(i);rows.addView(button(o.optString("name")+"  •  "+o.optString("type")+"  (Remove)",()->new AlertDialog.Builder(this).setMessage("Remove source?").setPositiveButton("Remove",(d,w)->{sources.remove(n);save();channels.clear();home();}).setNegativeButton("Cancel",null).show()));}return;}String q=search.getText().toString().toLowerCase(Locale.ROOT);for(Channel c:channels){if(tab.equals("Favorites")&&!favorites.contains(c.url()))continue;if(!(c.name()+" "+c.group()).toLowerCase(Locale.ROOT).contains(q))continue;LinearLayout line=new LinearLayout(this);line.addView(button(c.name()+"  •  "+c.group(),()->play(c)),new LinearLayout.LayoutParams(0,-2,1));line.addView(button(favorites.contains(c.url())?"★":"☆",()->{if(!favorites.add(c.url()))favorites.remove(c.url());save();render();}));rows.addView(line);}if(rows.getChildCount()==0)rows.addView(text("No channels / เพิ่มแหล่งสัญญาณ หรือกด Refresh",18));}
 void add(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"M3U","Direct","Xtream"}));l.addView(type);EditText name=field(l,"Name"),url=field(l,"HTTP(S) URL"),user=field(l,"Xtream username"),pass=field(l,"Xtream password");pass.setInputType(129);new AlertDialog.Builder(this).setTitle("Add source / เพิ่มแหล่งสัญญาณ").setView(l).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{String u=url.getText().toString().trim();if(!u.startsWith("http://")&&!u.startsWith("https://"))throw new Exception("HTTP(S) URL required");JSONObject o=new JSONObject();o.put("name",name.getText().toString());o.put("type",type.getSelectedItem().toString());o.put("url",u);o.put("user",user.getText().toString());o.put("pass",pass.getText().toString());sources.put(o);save();tab="All";load();}catch(Exception e){toast(e.getMessage());}}).show();}
 EditText field(LinearLayout l,String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);l.addView(e);return e;}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 void load(){final int g=++generation;final String snapshot=sources.toString();toast("Loading sources…");new Thread(()->{ArrayList<Channel> out=new ArrayList<>();int errors=0;try{JSONArray a=new JSONArray(snapshot);for(int i=0;i<a.length();i++){try{JSONObject o=a.getJSONObject(i);String u=o.getString("url"),t=o.getString("type");if(t.equals("Direct")){out.add(new Channel(o.optString("name"),u,"Direct"));continue;}if(t.equals("Xtream"))u=u.replaceAll("/+$","")+"/get.php?username="+enc(o.optString("user"))+"&password="+enc(o.optString("pass"))+"&type=m3u_plus&output=ts";URLConnection conn=new URL(u).openConnection();conn.setConnectTimeout(12000);conn.setReadTimeout(20000);try(BufferedReader r=new BufferedReader(new InputStreamReader(conn.getInputStream(),java.nio.charset.StandardCharsets.UTF_8))){String line,n=null,group="Live TV";while((line=r.readLine())!=null&&out.size()<20000){line=line.trim();if(line.startsWith("#EXTINF:")){int comma=line.lastIndexOf(',');n=comma>=0?line.substring(comma+1):"Channel";java.util.regex.Matcher m=java.util.regex.Pattern.compile("group-title=\"([^\"]*)\"").matcher(line);group=m.find()?m.group(1):"Live TV";}else if(!line.isEmpty()&&!line.startsWith("#")&&n!=null){String resolved=new URL(new URL(u),line).toString();out.add(new Channel(n,resolved,group));n=null;}}}}catch(Exception e){errors++;}}}catch(Exception e){errors++;}final int failed=errors;runOnUiThread(()->{if(g!=generation)return;channels=out;if(player==null)render();toast(out.size()+" channels; "+failed+" source errors");});}).start();}
 void play(Channel c){release();PlayerView view=new PlayerView(this);setContentView(view);player=new ExoPlayer.Builder(this).build();view.setPlayer(player);view.setUseController(true);player.setMediaItem(MediaItem.fromUri(c.url()));player.addListener(new Player.Listener(){public void onPlayerError(PlaybackException e){toast("Playback error: "+e.getErrorCodeName());}});player.prepare();player.play();view.requestFocus();}
 void release(){if(player!=null){player.release();player=null;}}
 @Override public void onBackPressed(){if(player!=null)home();else if(!tab.equals("All")){tab="All";home();}else super.onBackPressed();}
 @Override protected void onStop(){super.onStop();if(player!=null)player.pause();}
 @Override protected void onDestroy(){generation++;release();super.onDestroy();}
}
